#include "MemoryPatch.hpp"

#define WIN32_LEAN_AND_MEAN
#include <Windows.h>

namespace UE::Memory
{
	/*-----------------------------------------------------------------------------
		Addresses
	-----------------------------------------------------------------------------*/

	void* FImageMemory::Resolve(uint64 RelativeVirtualAddress, const wchar_t* ModuleName)
	{
		return UE::Interception::FModuleImage::ResolveRelativeAddress(RelativeVirtualAddress, ModuleName);
	}

	bool FImageMemory::IsInImage(uint64 RelativeVirtualAddress, SIZE_T Size, const wchar_t* ModuleName)
	{
		const SIZE_T ImageSize = UE::Interception::FModuleImage::GetImageSize(ModuleName);

		if (ImageSize == 0)
			return false;

		/* Written as a subtraction so an offset near the end of the image cannot overflow into looking valid. */
		return RelativeVirtualAddress < ImageSize && Size <= ImageSize - RelativeVirtualAddress;
	}

	/*-----------------------------------------------------------------------------
		Writing
	-----------------------------------------------------------------------------*/

	bool FImageMemory::PatchBytes(uint64 RelativeVirtualAddress, const void* Bytes, SIZE_T Size, const wchar_t* ModuleName)
	{
		if (Bytes == nullptr || Size == 0)
			return false;

		/* Both ends have to be inside the module: Resolve only vouches for the first byte. */
		if (!IsInImage(RelativeVirtualAddress, Size, ModuleName))
			return false;

		void* const Address = Resolve(RelativeVirtualAddress, ModuleName);

		if (Address == nullptr)
			return false;

		const UE::Interception::FScopedMemoryWriteAccess WriteAccess(Address, Size);

		if (!WriteAccess.IsValid())
			return false;

		std::memcpy(Address, Bytes, Size);

		return true;
	}

	bool FImageMemory::Patch(uint64 RelativeVirtualAddress, std::initializer_list<uint8> Bytes, const wchar_t* ModuleName)
	{
		return PatchBytes(RelativeVirtualAddress, Bytes.begin(), Bytes.size(), ModuleName);
	}

	bool FImageMemory::Nop(uint64 RelativeVirtualAddress, SIZE_T Size, const wchar_t* ModuleName)
	{
		if (Size == 0)
			return false;

		if (!IsInImage(RelativeVirtualAddress, Size, ModuleName))
			return false;

		void* const Address = Resolve(RelativeVirtualAddress, ModuleName);

		if (Address == nullptr)
			return false;

		const UE::Interception::FScopedMemoryWriteAccess WriteAccess(Address, Size);

		if (!WriteAccess.IsValid())
			return false;

		std::memset(Address, 0x90, Size);

		return true;
	}

	/*-----------------------------------------------------------------------------
		Disabling functions
	-----------------------------------------------------------------------------*/

	bool FImageMemory::Null(uint64 RelativeVirtualAddress, const wchar_t* ModuleName)
	{
		/* ret */
		const uint8 Ret = 0xC3;

		return PatchBytes(RelativeVirtualAddress, &Ret, sizeof(Ret), ModuleName);
	}

	bool FImageMemory::NullReturning(uint64 RelativeVirtualAddress, uint32 Value, const wchar_t* ModuleName)
	{
		if (Value == 0)
		{
			/* xor eax, eax; ret - clears all of RAX, so it reads as a null pointer as well as a zero. */
			const uint8 Bytes[] = { 0x31, 0xC0, 0xC3 };

			return PatchBytes(RelativeVirtualAddress, Bytes, sizeof(Bytes), ModuleName);
		}

		/* mov eax, Value; ret */
		uint8 Bytes[] = { 0xB8, 0x00, 0x00, 0x00, 0x00, 0xC3 };
		std::memcpy(&Bytes[1], &Value, sizeof(Value));

		return PatchBytes(RelativeVirtualAddress, Bytes, sizeof(Bytes), ModuleName);
	}

	/*-----------------------------------------------------------------------------
		Reading
	-----------------------------------------------------------------------------*/

	bool FImageMemory::ReadBytes(uint64 RelativeVirtualAddress, void* OutBytes, SIZE_T Size, const wchar_t* ModuleName)
	{
		if (OutBytes == nullptr || Size == 0)
			return false;

		if (!IsInImage(RelativeVirtualAddress, Size, ModuleName))
			return false;

		const void* const Address = Resolve(RelativeVirtualAddress, ModuleName);

		if (Address == nullptr)
			return false;

		std::memcpy(OutBytes, Address, Size);

		return true;
	}
}
